$('modalContent').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.target){const t=players.find(p=>p.id===Number(b.dataset.target));$('modal').close();activateHex(players[0],t)}else if(b.id==='startPrep'){$('modal').close();notice(players[0].role==='hider'?'准备开始，去找一片草丛藏身吧。':'躲藏者正在寻找藏身之处。你将在准备结束后出发。')}else if(b.id==='cancelTarget')$('modal').close();else if(b.id==='confirmSkip'){players.filter(p=>p.id!==0&&p.role==='hider').forEach(p=>Object.assign(p,pick(BRUSHES.filter(b=>canEnter(p,b.x,b.y)))));$('modal').close();hunt()}else if(b.id==='resumeGame'){paused=false;$('pause').textContent='Ⅱ';$('modal').close()}else if(b.id==='quitGame')reset()};
