// D is movement in WASD; Shift+D casts the D summoner spell, and the D HUD button is always available.
document.addEventListener('keydown',e=>{if(mode==='game'&&!paused&&!$('modal').open&&!$('help').open&&e.shiftKey&&e.key.toLowerCase()==='d'){e.preventDefault();keys.d=false;use(players[0],'d')}});
document.addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false});window.addEventListener('blur',()=>{keys={};if(mode==='game'&&!paused&&!$('modal').open&&!$('help').open)pauseGame()});document.addEventListener('visibilitychange',()=>{keys={};if(document.hidden&&mode==='game'&&!paused&&!$('modal').open&&!$('help').open)pauseGame()});window.addEventListener('resize',()=>{if(mode==='game')resize()});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();if(mode!=='game'||paused||$('modal').open||!rift)return;const pos=rift.groundPoint(e.clientX,e.clientY);if(!pos)return;const picked=rift.pickUnit(e.clientX,e.clientY);const enemy=activeEnemies(players[0]).find(p=>visible(players[0],p)&&(p.id===picked||dist(pos,p)<24));if(enemy){players[0].target={x:enemy.x,y:enemy.y};if(players[0].role==='seeker'||duel){players[0].attackTarget=enemy.id;if(dist(players[0],enemy)<150)attack(players[0],enemy)}}else if(canEnter(players[0],pos.x,pos.y)){players[0].target=pos;players[0].attackTarget=null;rift.clickMarker(pos)}else toast('这里不可通行，请选择下半区的地面');canvas.focus()});
let orbitDrag=null;
canvas.addEventListener('pointerdown',e=>{if(paused||$('modal').open||!rift)return;if(e.button===0||e.button===1){orbitDrag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);e.preventDefault()}canvas.focus()});
canvas.addEventListener('pointermove',e=>{if(!orbitDrag||e.pointerId!==orbitDrag.id)return;const dx=e.clientX-orbitDrag.x,dy=e.clientY-orbitDrag.y;if(Math.hypot(e.clientX-orbitDrag.startX,e.clientY-orbitDrag.startY)>5)orbitDrag.moved=true;if(orbitDrag.moved)rift.orbit(dx,dy);orbitDrag.x=e.clientX;orbitDrag.y=e.clientY});
canvas.addEventListener('pointerup',e=>{if(!orbitDrag)return;if(!orbitDrag.moved&&e.button===0&&!paused&&!$('modal').open){const pos=rift.groundPoint(e.clientX,e.clientY);if(pos){const picked=rift.pickUnit(e.clientX,e.clientY);const t=activeEnemies(players[0]).find(p=>visible(players[0],p)&&(p.id===picked||dist(pos,p)<26));if(t)attack(players[0],t);else if(e.pointerType==='touch'&&canEnter(players[0],pos.x,pos.y)){players[0].target=pos;players[0].attackTarget=null;rift.clickMarker(pos)}}}orbitDrag=null});
canvas.addEventListener('pointercancel',()=>orbitDrag=null);canvas.addEventListener('wheel',e=>{if(rift&&mode==='game'){e.preventDefault();rift.zoom(e.deltaY)}},{passive:false});
$('qualitySelect').onchange=e=>{if(rift)rift.setQuality(e.target.value)};$('cameraReset').onclick=()=>{if(rift)rift.resetCamera()};$('cameraNear').onclick=()=>{if(rift)rift.setView('near')};$('cameraTactical').onclick=()=>{if(rift)rift.setView('tactical')};
document.querySelectorAll('[data-move]').forEach(b=>{const map={up:'ArrowUp',left:'ArrowLeft',down:'ArrowDown',right:'ArrowRight'};b.addEventListener('pointerdown',e=>{e.preventDefault();keys[map[b.dataset.move]]=true;b.setPointerCapture(e.pointerId)});for(const event of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys[map[b.dataset.move]]=false)});
document.querySelector('.controls-hint').innerHTML='WASD 移动 <em>·</em> 右键 行走 / 抓捕 <em>·</em> 拖动画面 旋转镜头 <em>·</em> 滚轮 缩放 <em>·</em> 空格 抓捕 <em>·</em> Esc 暂停';
roll();
